/**
 * Translations for all supported languages
 * 
 * Structure: translations[languageCode][translationKey] = translatedText
 * 
 * To add a new language:
 * 1. Add a new language code entry (e.g., 'es': {...})
 * 2. Copy all keys from 'en' and translate the values
 * 3. Update languages.ts to add the language config
 * 
 * The app will automatically support the new language!
 */

// Define translation structure for better type safety
interface TranslationSet {
  [key: string]: string;
}

interface TranslationsMap {
  [languageCode: string]: TranslationSet;
}

